import React, { useEffect, useState } from 'react';
import { applicationsAPI } from '../../services/api';

interface Application {
  _id: string;
  name: string;
  version: string;
  vendor: string;
  status: string;
  createdAt: string;
}

const Applications: React.FC = () => {
  const [applications, setApplications] = useState<Application[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [showForm, setShowForm] = useState(false);
  const [formData, setFormData] = useState<Partial<Application>>({});
  const [editingId, setEditingId] = useState<string | null>(null);

  const fetchApplications = async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await applicationsAPI.getAll();
      setApplications(res.data.applications || []);
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to fetch applications');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchApplications();
  }, []);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await applicationsAPI.create(formData);
      setShowForm(false);
      setFormData({});
      fetchApplications();
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to create application');
    }
  };

  const handleEdit = (app: Application) => {
    setEditingId(app._id);
    setFormData(app);
    setShowForm(true);
  };

  const handleUpdate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingId) return;
    try {
      await applicationsAPI.update(editingId, formData);
      setShowForm(false);
      setEditingId(null);
      setFormData({});
      fetchApplications();
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to update application');
    }
  };

  const handleDelete = async (id: string) => {
    if (!window.confirm('Are you sure you want to delete this application?')) return;
    try {
      await applicationsAPI.delete(id);
      fetchApplications();
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to delete application');
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-semibold text-gray-900 dark:text-white">
            Applications
          </h1>
          <p className="mt-1 text-sm text-gray-600 dark:text-gray-400">
            Manage your infrastructure applications
          </p>
        </div>
        <button
          className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700"
          onClick={() => {
            setShowForm(true);
            setEditingId(null);
            setFormData({});
          }}
        >
          + Add Application
        </button>
      </div>

      {showForm && (
        <form
          className="bg-white dark:bg-gray-800 shadow rounded-lg p-6 space-y-4"
          onSubmit={editingId ? handleUpdate : handleCreate}
        >
          <div className="flex space-x-4">
            <input
              type="text"
              name="name"
              placeholder="Name"
              value={formData.name || ''}
              onChange={handleInputChange}
              className="border rounded px-3 py-2 flex-1"
              required
            />
            <input
              type="text"
              name="version"
              placeholder="Version"
              value={formData.version || ''}
              onChange={handleInputChange}
              className="border rounded px-3 py-2 flex-1"
              required
            />
            <input
              type="text"
              name="vendor"
              placeholder="Vendor"
              value={formData.vendor || ''}
              onChange={handleInputChange}
              className="border rounded px-3 py-2 flex-1"
              required
            />
            <select
              name="status"
              value={formData.status || 'active'}
              onChange={handleInputChange}
              className="border rounded px-3 py-2 flex-1"
            >
              <option value="active">Active</option>
              <option value="deprecated">Deprecated</option>
              <option value="eol">EOL</option>
              <option value="eosl">EOSL</option>
              <option value="unknown">Unknown</option>
            </select>
          </div>
          <div className="flex space-x-4">
            <button
              type="submit"
              className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700"
            >
              {editingId ? 'Update' : 'Create'}
            </button>
            <button
              type="button"
              className="bg-gray-300 text-gray-800 px-4 py-2 rounded hover:bg-gray-400"
              onClick={() => {
                setShowForm(false);
                setEditingId(null);
                setFormData({});
              }}
            >
              Cancel
            </button>
          </div>
        </form>
      )}

      {loading ? (
        <div className="text-center text-gray-500 dark:text-gray-400 py-8">Loading...</div>
      ) : error ? (
        <div className="text-center text-red-500 py-8">{error}</div>
      ) : (
        <div className="bg-white dark:bg-gray-800 shadow rounded-lg p-6">
          {applications.length === 0 ? (
            <div className="text-center text-gray-500 dark:text-gray-400 py-8">
              No applications found
            </div>
          ) : (
            <table className="min-w-full divide-y divide-gray-200 dark:divide-gray-700">
              <thead>
                <tr>
                  <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase">Name</th>
                  <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase">Version</th>
                  <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase">Vendor</th>
                  <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase">Status</th>
                  <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase">Created</th>
                  <th className="px-4 py-2"></th>
                </tr>
              </thead>
              <tbody>
                {applications.map((app) => (
                  <tr key={app._id} className="hover:bg-gray-50 dark:hover:bg-gray-700">
                    <td className="px-4 py-2">{app.name}</td>
                    <td className="px-4 py-2">{app.version}</td>
                    <td className="px-4 py-2">{app.vendor}</td>
                    <td className="px-4 py-2 capitalize">{app.status}</td>
                    <td className="px-4 py-2">{new Date(app.createdAt).toLocaleDateString()}</td>
                    <td className="px-4 py-2 space-x-2">
                      <button
                        className="bg-yellow-500 text-white px-2 py-1 rounded hover:bg-yellow-600"
                        onClick={() => handleEdit(app)}
                      >
                        Edit
                      </button>
                      <button
                        className="bg-red-600 text-white px-2 py-1 rounded hover:bg-red-700"
                        onClick={() => handleDelete(app._id)}
                      >
                        Delete
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      )}
    </div>
  );
};

export default Applications;
